/* XLWebEngineUI: deferred functional selectors return after a candidate was
 * found. A failed candidate must resume the same compound's relational search,
 * not discard its remaining ancestors/siblings/descendants. */
lxb_inline bool
lxb_selectors_retry_compound(lxb_selectors_t *selectors,
                              lxb_selectors_nested_t *current)
{
    lxb_selectors_entry_t *first = current->entry;
    lxb_dom_node_t *node = first->node;
    while (first->combinator == LXB_CSS_SELECTOR_COMBINATOR_CLOSE
           && (current->forward ? first->prev : first->next) != NULL)
    {
        first = current->forward ? first->prev : first->next;
    }
    if (first->combinator != LXB_CSS_SELECTOR_COMBINATOR_DESCENDANT
        && first->combinator != LXB_CSS_SELECTOR_COMBINATOR_FOLLOWING
        && !(current->forward
             && first->combinator == LXB_CSS_SELECTOR_COMBINATOR_CHILD))
    {
        return false;
    }
    first->node = node;
    current->entry = first;
    selectors->state = current->forward ? lxb_selectors_state_find_forward
                                       : lxb_selectors_state_find;
    return true;
}

